// The ticker list comes from the "Ticker list (edit here)" node — edit it THERE, not in code.
const raw = $('Ticker list (edit here)').first().json.tickers || '';
const WIG20 = String(raw).split(',').map((s) => s.trim().toUpperCase()).filter(Boolean);
if (WIG20.length === 0) { throw new Error('Pusta lista spółek — uzupełnij węzeł "Ticker list (edit here)"'); }
const base = 'http://stock-api:8000';
const H = this.helpers;

// Sentiment is ~95% of the payload: one ticker ships 128 Google News items whose
// base64 redirect URLs alone cost ~10k tokens. Stripping them plus a 90-day window
// takes a ticker from ~33k to ~9k tokens — that is what blew the 1M limit.
const NEWS_WINDOW_DAYS = 90;
const MAX_MENTIONS_PER_SOURCE = 40;

function sleep(ms) { return new Promise((r) => setTimeout(r, ms)); }

// Fetched SEQUENTIALLY — concurrency breaks yfinance (401 "Invalid Crumb").
// One retry with backoff in case of a transient block. ~70s for the whole WIG20.
async function g(path) {
  for (let attempt = 0; attempt < 2; attempt++) {
    try { return await H.httpRequest({ url: base + path, json: true, timeout: 60000 }); }
    catch (e) {
      if (attempt === 0) { await sleep(1200); continue; }
      return { error: String((e && e.message) || e) };
    }
  }
}

function trimSentiment(s) {
  if (!s || !Array.isArray(s.results)) { return s; }
  const cutoff = Date.now() - NEWS_WINDOW_DAYS * 86400000;
  for (const src of s.results) {
    const mentions = Array.isArray(src.mentions) ? src.mentions : [];
    const dated = [];
    const undated = [];
    for (const m of mentions) {
      const t = m.date ? Date.parse(m.date) : NaN;
      if (Number.isNaN(t)) { undated.push(m); }        // Bankier ships no dates — keep them
      else if (t >= cutoff) { dated.push([t, m]); }
    }
    // Mentions arrive UNSORTED (Google News mixes in items from 2004), so sorting
    // before the cap is what makes the cap drop the oldest instead of random ones.
    dated.sort((a, b) => b[0] - a[0]);
    const kept = [...dated.map((p) => p[1]), ...undated].slice(0, MAX_MENTIONS_PER_SOURCE);
    src.mentions = kept.map((m) => {
      const { url, ...rest } = m;                       // URLs are never cited in the e-mail
      return rest;
    });
    src.mentions_shown = src.mentions.length;           // total_mentions/overall_score untouched
  }
  return s;
}

const macro = await g('/macro');
const out = [];
for (const t of WIG20) {
  const technical = await g(`/technical/${t}`);
  const fundamental = await g(`/fundamental/${t}`);
  const dcf = await g(`/dcf/${t}`);
  const sentiment = trimSentiment(await g(`/sentiment/${t}`));
  const speculator = await g(`/speculator/${t}`);
  const dane = { technical, fundamental, dcf, sentiment, speculator };
  // Compact JSON, not indent:1 — pretty-printing added ~30% for zero benefit.
  const prompt = `Spółka ${t}. Surowe dane wszystkich agentów:\n${JSON.stringify(dane)}`;
  out.push({
    json: {
      ticker: t,
      prompt,
      quality: (technical && technical.data_quality) || null,
      macro,
      chars: prompt.length,
    },
  });
}
return out;

// Parses the per-ticker review back into {bucket, line, horizons, details}.
// Marker-based rather than JSON, because `claude -p` returns prose and wraps JSON in fences.
const res = $input.first().json;
const ticker = $('Loop over tickers').first().json.ticker;
const quality = $('Loop over tickers').first().json.quality || null;

const HORIZON_CODES = ['7D', '2T', '1M', '3M', '1R', 'LT'];

function emptyHorizons() {
  return HORIZON_CODES.map((code) => ({ code, verdict: 'BRAK', why: '' }));
}

if (res.error || !res.response) {
  const why = String(res.error || 'brak odpowiedzi z proxy');
  return [{ json: { ticker, bucket: '🟡', line: `${ticker} — BŁĄD ANALIZY: ${why}`, details: '',
                    horizons: emptyHorizons(), quality, failed: true } }];
}

const raw = String(res.response);
function section(name, next) {
  const re = new RegExp(`###${name}###\\s*([\\s\\S]*?)(?=###(?:${next})###|$)`);
  const m = raw.match(re);
  return m ? m[1].trim() : '';
}
const bucketRaw = section('KOSZYK', 'LINIA|HORYZONTY|SZCZEGOLY');
const line = section('LINIA', 'HORYZONTY|SZCZEGOLY');
const horizonsRaw = section('HORYZONTY', 'SZCZEGOLY|LINIA');
const details = section('SZCZEGOLY', 'KOSZYK|HORYZONTY');

// "7D | KUPUJ | uzasadnienie" — tolerant of bold, stray spaces and a missing third cell.
function verdictOf(text) {
  const t = String(text).toUpperCase();
  if (t.includes('SPRZEDAJ')) { return 'SPRZEDAJ'; }
  if (t.includes('KUPUJ')) { return 'KUPUJ'; }
  if (t.includes('TRZYMAJ')) { return 'TRZYMAJ'; }
  return 'BRAK';
}
function parseHorizons(text) {
  const found = {};
  for (const row of String(text).split('\n')) {
    const cells = row.split('|');
    if (cells.length < 2) { continue; }
    const code = cells[0].replace(/[*`\s.]/g, '').toUpperCase();
    if (!HORIZON_CODES.includes(code) || found[code]) { continue; }
    found[code] = { code, verdict: verdictOf(cells[1]), why: cells.slice(2).join('|').trim() };
  }
  // Never drop a horizon: a missing row shows as "brak danych", not as a gap in the table.
  return HORIZON_CODES.map((code) => found[code] || { code, verdict: 'BRAK', why: '' });
}

// Fallback when the model ignores the format: never drop a company from the report.
const bucket = ['🟢', '🔴', '🟡'].find((b) => bucketRaw.includes(b)) || '🟡';
const firstLine = raw.split('\n').map((s) => s.trim()).filter(Boolean)[0] || `${ticker} — brak treści`;

return [{ json: { ticker, bucket, line: line || firstLine, horizons: parseHorizons(horizonsRaw),
                  details, quality, failed: false } }];

// Reduce stage: 20 one-liners (~15k tokens total) instead of 20x raw JSON.
const spolki = $input.all().map((i) => i.json);
const macro = $('Fetch data (sequential)').first().json.macro;
const kiedy = new Date().toLocaleString('pl-PL', { timeZone: 'Europe/Warsaw' });

const swiezosc = spolki.map((s) => {
  const q = s.quality || {};
  return `${s.ticker}: last_date=${q.last_date ?? '?'} is_stale=${q.is_stale ?? '?'} missing_sessions=${q.missing_sessions ?? '?'}`;
}).join('\n');

const linie = spolki.map((s) => `${s.bucket} ${s.line}`).join('\n');

const prompt =
  `Dzienny przegląd WIG20. Data/godzina: ${kiedy}. Spółek: ${spolki.length}.\n\n` +
  `OCENY SPÓŁEK (koszyk już przypisany):\n${linie}\n\n` +
  `ŚWIEŻOŚĆ DANYCH:\n${swiezosc}\n\n` +
  `MAKRO:\n${JSON.stringify(macro)}`;

return [{ json: { prompt, spolki } }];

// Builds the e-mail: HTML (primary) + plain-text fallback.
// Part 1 comes from the ranking call, Part 2 is stitched from the per-ticker blocks —
// no LLM ever has to hold all 20 companies' raw data at once.
// The ranking stage returns ONLY the order of tickers: the one-liners reach the reader
// exactly as the per-ticker stage wrote them (an LLM retyping 20 lines loses digits).
// Freshness banner and bucket counts are computed HERE, not by the model — they are
// pure arithmetic over `quality`, so there is no reason to let a prompt get them wrong.
const res = $input.first().json;
const spolki = $('Build ranking prompt').first().json.spolki;

const TZ = 'Europe/Warsaw';
const now = new Date();
const dzis = now.toLocaleDateString('pl-PL', { timeZone: TZ, day: '2-digit', month: '2-digit', year: 'numeric' });
const godzina = now.toLocaleTimeString('pl-PL', { timeZone: TZ, hour: '2-digit', minute: '2-digit' });

const BUCKETS = [
  { emoji: '🟢', label: 'Najciekawsze', hint: 'spójny sygnał w górę', fg: '#0b6b3a', bg: '#e9f7ef', line: '#bfe3cd' },
  { emoji: '🔴', label: 'Wysokie ryzyko', hint: 'sygnał w dół lub rozbieżność na niekorzyść', fg: '#a8201a', bg: '#fdecea', line: '#f3c7c3' },
  { emoji: '🟡', label: 'Obserwacja', hint: 'brak wyraźnego sygnału', fg: '#8a6100', bg: '#fff7e6', line: '#f0dda8' },
];
// Six horizons per company, rendered as a strip in part 1 and as a table in part 2.
// The wording deliberately stays "ocena", not "rekomendacja" — see the footer disclaimer.
const HORIZONS = [
  { code: '7D', label: '7 dni' },
  { code: '2T', label: '2 tyg.' },
  { code: '1M', label: 'miesiąc' },
  { code: '3M', label: '3 mies.' },
  { code: '1R', label: 'rok' },
  { code: 'LT', label: 'długi term.' },
];
const VERDICTS = {
  KUPUJ: { mark: '▲', fg: '#0b6b3a', bg: '#e9f7ef', line: '#bfe3cd' },
  SPRZEDAJ: { mark: '▼', fg: '#a8201a', bg: '#fdecea', line: '#f3c7c3' },
  TRZYMAJ: { mark: '●', fg: '#8a6100', bg: '#fff7e6', line: '#f0dda8' },
  BRAK: { mark: '·', fg: '#7b8794', bg: '#f2f4f6', line: '#e0e4e9' },
};
const FONT = "-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif";
const MONO = "ui-monospace,SFMono-Regular,Menlo,Consolas,'Liberation Mono',monospace";
const INK = '#1c2430';
const MUTED = '#5d6b7a';
const RULE = '#e4e8ed';

// ── parsing the ranking answer ────────────────────────────────────────────────
function section(raw, name, next) {
  const m = String(raw).match(new RegExp(`###${name}###\\s*([\\s\\S]*?)(?=###(?:${next})###|$)`));
  return m ? m[1].trim() : '';
}

const rankingOk = !(res.error || !res.response);
const rankingRaw = rankingOk ? String(res.response) : '';
const naglowek = rankingOk ? section(rankingRaw, 'NAGLOWEK', 'KOLEJNOSC|MAKRO') : '';
const kolejnoscRaw = rankingOk ? section(rankingRaw, 'KOLEJNOSC', 'MAKRO|NAGLOWEK') : '';
const makro = rankingOk ? section(rankingRaw, 'MAKRO', 'NAGLOWEK|KOLEJNOSC') : '';
const rankingBlad = rankingOk ? '' : String(res.error || 'brak odpowiedzi z proxy');

// "🟢: PKO, CDR, PEO" per line → order of tickers inside each bucket.
const kolejnosc = {};
for (const wiersz of kolejnoscRaw.split('\n')) {
  const b = BUCKETS.map((x) => x.emoji).find((e) => wiersz.includes(e));
  if (!b) { continue; }
  kolejnosc[b] = wiersz
    .slice(wiersz.indexOf(b) + b.length)
    .replace(/^[\s:—–-]+/, '')
    .split(/[,;]/)
    .map((s) => s.trim().toUpperCase())
    .filter((s) => /^[A-Z0-9.]{1,10}$/.test(s));
}

function wKoszyku(emoji) {
  const lista = spolki.filter((s) => s.bucket === emoji);
  const order = kolejnosc[emoji] || [];
  return lista
    .map((s, i) => {
      const p = order.indexOf(String(s.ticker).toUpperCase());
      return { s, rank: p === -1 ? order.length + i : p };
    })
    .sort((a, b) => a.rank - b.rank)
    .map((x) => x.s);
}

// One-liners arrive as "PKO — sygnał"; the ticker is shown as a badge, so strip it.
function trescLinii(s) {
  const m = String(s.line || '').match(/^\s*([A-Z0-9.]{1,10})\s*[—–-]\s*([\s\S]+)$/);
  return m && m[1].toUpperCase() === String(s.ticker).toUpperCase() ? m[2].trim() : String(s.line || '').trim();
}

// ── freshness, computed from data (never from the model) ──────────────────────
const daty = spolki.map((s) => (s.quality || {}).last_date).filter(Boolean).sort();
// last_date arrives as YYYY-MM-DD; the report speaks dd.MM.yyyy everywhere else.
const plData = (d) => { const m = String(d).match(/^(\d{4})-(\d{2})-(\d{2})/); return m ? `${m[3]}.${m[2]}.${m[1]}` : String(d); };
const sesja = daty.length ? plData(daty[daty.length - 1]) : null;
const nieswieze = spolki
  .filter((s) => { const q = s.quality || {}; return q.is_stale === true || (q.missing_sessions || 0) >= 1; })
  .map((s) => { const q = s.quality || {}; const n = q.missing_sessions || 0; return n ? `${s.ticker} (${n})` : String(s.ticker); });
const bledy = spolki.filter((s) => s.failed).map((s) => s.ticker);
const liczniki = BUCKETS.map((b) => ({ ...b, n: spolki.filter((s) => s.bucket === b.emoji).length }));

// ── markdown → HTML (bold/italic/code, bullets, paragraphs) ───────────────────
function esc(t) {
  return String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
function inline(t) {
  return esc(t)
    .replace(/`([^`]+)`/g, `<code style="font-family:${MONO};font-size:12px;background:#f1f3f6;border-radius:3px;padding:1px 4px;">$1</code>`)
    .replace(/\*\*([^*]+)\*\*/g, '<strong style="color:' + INK + ';">$1</strong>')
    .replace(/(^|[\s(])\*([^*\n]+)\*/g, '$1<em>$2</em>');
}
function md(text) {
  const out = [];
  let para = [];
  let items = [];
  const P = `margin:0 0 10px;font-size:14px;line-height:1.62;color:${INK};`;
  const flushP = () => { if (para.length) { out.push(`<p style="${P}">${para.join('<br>')}</p>`); para = []; } };
  const flushL = () => {
    if (items.length) {
      out.push(`<ul style="margin:0 0 10px;padding-left:20px;">${items.map((i) => `<li style="${P}margin:0 0 5px;">${i}</li>`).join('')}</ul>`);
      items = [];
    }
  };
  for (const surowa of String(text || '').split('\n')) {
    const l = surowa.trim();
    if (!l) { flushP(); flushL(); continue; }
    const b = l.match(/^(?:[-*•·]|\d+[.)])\s+([\s\S]*)$/);
    if (b) { flushP(); items.push(inline(b[1])); continue; }
    flushL();
    para.push(inline(l));
  }
  flushP(); flushL();
  return out.join('') || `<p style="${P}">—</p>`;
}

// The per-ticker prompt asks for **Fakty** / **Model** / **Interpretacja**; split on
// those headers so each gets its own labelled block instead of one wall of text.
const ETYKIETY = ['Fakty', 'Model', 'Interpretacja'];
function rozbijSzczegoly(text) {
  const src = String(text || '');
  const re = /(?:^|\n)[ \t]*(?:#{1,4}[ \t]*)?\**[ \t]*(Fakty|Model|Interpretacja)[ \t]*\**[ \t]*[:—–-]?[ \t]*/gi;
  const trafienia = [];
  let m;
  while ((m = re.exec(src)) !== null) {
    trafienia.push({ label: ETYKIETY.find((e) => e.toLowerCase() === m[1].toLowerCase()), start: m.index, end: re.lastIndex });
  }
  if (!trafienia.length) { return [{ label: null, body: src.trim() }]; }
  const bloki = [];
  const wstep = src.slice(0, trafienia[0].start).trim();
  if (wstep) { bloki.push({ label: null, body: wstep }); }
  trafienia.forEach((t, i) => {
    const koniec = i + 1 < trafienia.length ? trafienia[i + 1].start : src.length;
    bloki.push({ label: t.label, body: src.slice(t.end, koniec).trim() });
  });
  return bloki.filter((b) => b.body);
}

// ── HTML ──────────────────────────────────────────────────────────────────────
const H = [];
function kropka(fg) {
  return `<span style="display:inline-block;width:9px;height:9px;border-radius:50%;background:${fg};vertical-align:middle;"></span>`;
}
function badge(ticker, fg, bg, line) {
  return `<span style="display:inline-block;font-family:${MONO};font-size:12px;font-weight:700;letter-spacing:.03em;color:${fg};background:${bg};border:1px solid ${line};border-radius:5px;padding:2px 7px;">${esc(ticker)}</span>`;
}

function horizonsOf(s) {
  const byCode = Object.fromEntries((s.horizons || []).map((h) => [h.code, h]));
  return HORIZONS.map((h) => ({ ...h, ...(byCode[h.code] || { verdict: 'BRAK', why: '' }) }));
}

// Compact strip: one cell per horizon, mark + label. Table cells rather than flex —
// this has to survive Outlook.
function horizonStrip(s) {
  const cells = horizonsOf(s).map((h) => {
    const v = VERDICTS[h.verdict] || VERDICTS.BRAK;
    return `<td align="center" style="padding:3px 2px;">`
      + `<div style="font-size:9px;letter-spacing:.05em;text-transform:uppercase;color:${MUTED};white-space:nowrap;">${h.label}</div>`
      + `<div style="margin-top:2px;font-size:13px;line-height:1.1;font-weight:700;color:${v.fg};background:${v.bg};border:1px solid ${v.line};border-radius:4px;padding:2px 0;">${v.mark}</div>`
      + `</td>`;
  }).join('');
  return `<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="margin-top:8px;table-layout:fixed;"><tr>${cells}</tr></table>`;
}

function horizonTable(s) {
  const rows = horizonsOf(s).map((h) => {
    const v = VERDICTS[h.verdict] || VERDICTS.BRAK;
    const verdictText = h.verdict === 'BRAK' ? 'brak danych' : h.verdict.toLowerCase();
    return `<tr>`
      + `<td valign="top" style="padding:6px 10px 6px 0;font-size:11px;letter-spacing:.05em;text-transform:uppercase;color:${MUTED};white-space:nowrap;border-top:1px solid ${RULE};">${h.label}</td>`
      + `<td valign="top" style="padding:6px 10px 6px 0;white-space:nowrap;border-top:1px solid ${RULE};">`
      + `<span style="display:inline-block;font-size:11px;font-weight:700;color:${v.fg};background:${v.bg};border:1px solid ${v.line};border-radius:4px;padding:1px 7px;">${v.mark} ${esc(verdictText)}</span></td>`
      + `<td valign="top" style="padding:6px 0;font-size:13px;line-height:1.5;color:${INK};border-top:1px solid ${RULE};">${h.why ? inline(h.why) : '<span style="color:' + MUTED + ';">—</span>'}</td>`
      + `</tr>`;
  }).join('');
  return `<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%">${rows}</table>`;
}

H.push(`<!doctype html><html lang="pl"><head><meta charset="utf-8">`);
H.push(`<meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light only">`);
H.push(`<title>WIG20 — przegląd dzienny ${dzis}</title></head>`);
H.push(`<body style="margin:0;padding:0;background:#eef1f4;-webkit-text-size-adjust:100%;">`);
H.push(`<div style="display:none;max-height:0;overflow:hidden;opacity:0;">${liczniki.map((b) => `${b.n} ${b.label.toLowerCase()}`).join(' · ')}</div>`);
H.push(`<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#eef1f4;"><tr><td align="center" style="padding:24px 12px;">`);
H.push(`<table role="presentation" width="680" cellpadding="0" cellspacing="0" border="0" style="width:100%;max-width:680px;background:#ffffff;border:1px solid ${RULE};border-radius:14px;overflow:hidden;font-family:${FONT};">`);

// Header
H.push(`<tr><td style="background:#16202e;padding:22px 26px;">`);
H.push(`<div style="font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:#8fa3b8;">Przegląd dzienny</div>`);
H.push(`<div style="font-size:23px;font-weight:700;color:#ffffff;margin-top:4px;">WIG20 · ${dzis}</div>`);
H.push(`<div style="font-size:13px;color:#9fb2c6;margin-top:6px;">Wygenerowano ${godzina}${sesja ? ` · dane z sesji ${sesja}` : ''} · ${spolki.length} spółek</div>`);
H.push(`</td></tr>`);

// Bucket counters
H.push(`<tr><td style="padding:16px 26px 6px;border-bottom:1px solid ${RULE};">`);
H.push(`<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%"><tr>`);
liczniki.forEach((b, i) => {
  H.push(`<td width="33%" style="padding:0 ${i === liczniki.length - 1 ? '0' : '6px'} 10px 0;"><table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="background:${b.bg};border:1px solid ${b.line};border-radius:9px;"><tr><td style="padding:10px 12px;">`);
  H.push(`<div style="font-size:22px;font-weight:700;color:${b.fg};line-height:1.1;">${b.n}</div>`);
  H.push(`<div style="font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:${b.fg};opacity:.85;margin-top:3px;">${b.label}</div>`);
  H.push(`</td></tr></table></td>`);
});
H.push(`</tr></table></td></tr>`);

// Warnings
const ostrzezenia = [];
if (nieswieze.length) {
  ostrzezenia.push(`<strong>Nieświeże dane</strong> (w nawiasie brakujące sesje): ${esc(nieswieze.join(', '))}. Kursy i wskaźniki tych spółek pochodzą sprzed ostatniej sesji.`);
}
if (bledy.length) {
  ostrzezenia.push(`<strong>Bez analizy</strong> (błąd wywołania): ${esc(bledy.join(', '))}.`);
}
if (!rankingOk) {
  ostrzezenia.push(`<strong>Etap rankingu nie odpowiedział</strong> (${esc(rankingBlad)}) — kolejność w koszykach jest domyślna, brak komentarza makro.`);
}
if (ostrzezenia.length) {
  H.push(`<tr><td style="padding:14px 26px 0;">`);
  H.push(`<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="background:#fff7e6;border:1px solid #f0dda8;border-left:4px solid #e0a800;border-radius:8px;"><tr><td style="padding:11px 14px;font-size:13px;line-height:1.55;color:#6b4e00;">`);
  H.push(ostrzezenia.map((o) => `<div style="margin:0 0 4px;">⚠️ ${o}</div>`).join(''));
  H.push(`</td></tr></table></td></tr>`);
}

// Headline
if (naglowek) {
  H.push(`<tr><td style="padding:18px 26px 0;"><div style="font-size:15px;line-height:1.6;color:${INK};border-left:3px solid #16202e;padding-left:14px;">${md(naglowek).replace(/margin:0 0 10px;/g, 'margin:0 0 8px;')}</div></td></tr>`);
}

// Part 1 — buckets
H.push(`<tr><td style="padding:22px 26px 4px;">`);
H.push(`<div style="font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:${MUTED};border-bottom:1px solid ${RULE};padding-bottom:8px;">Część 1 · Przegląd</div>`);
H.push(`</td></tr>`);

for (const b of BUCKETS) {
  const lista = wKoszyku(b.emoji);
  H.push(`<tr><td style="padding:16px 26px 0;">`);
  H.push(`<div style="margin:0 0 9px;">${kropka(b.fg)} <span style="font-size:14px;font-weight:700;color:${INK};letter-spacing:.02em;">${b.label}</span> <span style="font-size:12px;color:${MUTED};">· ${lista.length} · ${b.hint}</span></div>`);
  if (!lista.length) {
    H.push(`<div style="font-size:13px;color:${MUTED};padding:8px 0 2px;">— brak spółek w tym koszyku</div>`);
  } else {
    H.push(`<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="background:${b.bg};border:1px solid ${b.line};border-radius:10px;">`);
    lista.forEach((s, i) => {
      H.push(`<tr><td style="padding:11px 14px;${i ? `border-top:1px solid ${b.line};` : ''}">`);
      H.push(`<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%"><tr>`);
      H.push(`<td width="66" valign="top" style="padding:1px 10px 0 0;white-space:nowrap;">${badge(s.ticker, b.fg, '#ffffff', b.line)}</td>`);
      H.push(`<td valign="top" style="font-size:14px;line-height:1.55;color:${INK};">${inline(trescLinii(s))}${horizonStrip(s)}</td>`);
      H.push(`</tr></table></td></tr>`);
    });
    H.push(`</table>`);
  }
  H.push(`</td></tr>`);
}

// Macro
if (makro) {
  H.push(`<tr><td style="padding:22px 26px 0;">`);
  H.push(`<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="background:#f5f7f9;border:1px solid ${RULE};border-radius:10px;"><tr><td style="padding:14px 16px;">`);
  H.push(`<div style="font-size:11px;letter-spacing:.12em;text-transform:uppercase;color:${MUTED};margin-bottom:7px;">Tło makro</div>`);
  H.push(md(makro));
  H.push(`</td></tr></table></td></tr>`);
}

// Part 2 — details for 🟢/🔴
const zeSzczegolami = BUCKETS.filter((b) => b.emoji !== '🟡').flatMap((b) => wKoszyku(b.emoji).filter((s) => s.details).map((s) => ({ s, b })));
if (zeSzczegolami.length) {
  H.push(`<tr><td style="padding:26px 26px 4px;">`);
  H.push(`<div style="font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:${MUTED};border-bottom:1px solid ${RULE};padding-bottom:8px;">Część 2 · Szczegóły (${zeSzczegolami.length})</div>`);
  H.push(`</td></tr>`);
  for (const { s, b } of zeSzczegolami) {
    H.push(`<tr><td style="padding:16px 26px 0;">`);
    H.push(`<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="border:1px solid ${RULE};border-left:4px solid ${b.fg};border-radius:10px;"><tr><td style="padding:0;">`);
    H.push(`<div style="padding:12px 16px;background:${b.bg};border-bottom:1px solid ${RULE};">`);
    H.push(`${badge(s.ticker, b.fg, '#ffffff', b.line)} <span style="font-size:13px;color:${INK};line-height:1.5;">${inline(trescLinii(s))}</span></div>`);
    H.push(`<div style="padding:14px 16px 4px;">`);
    H.push(`<div style="font-size:10px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:${MUTED};margin:0 0 4px;">Ocena w horyzontach</div>`);
    H.push(`<div style="margin:0 0 14px;">${horizonTable(s)}</div>`);
    for (const blok of rozbijSzczegoly(s.details)) {
      if (blok.label) {
        H.push(`<div style="font-size:10px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:${MUTED};margin:0 0 6px;">${blok.label}</div>`);
      }
      H.push(`<div style="margin:0 0 12px;">${md(blok.body)}</div>`);
    }
    H.push(`</div></td></tr></table></td></tr>`);
  }
}

// Footer
H.push(`<tr><td style="padding:26px 26px 24px;">`);
H.push(`<div style="border-top:1px solid ${RULE};padding-top:14px;font-size:11px;line-height:1.65;color:${MUTED};">`);
H.push(`Raport wygenerowany automatycznie przez stock-agents (dane: yfinance, Biznesradar, NBP, Bankier, Stockwatch, Google News) i podsumowany przez model językowy.<br>`);
H.push(`<strong style="color:${INK};">To analiza danych, nie rekomendacja inwestycyjna.</strong> Liczby pochodzą wyłącznie z odpowiedzi API; projekcje nie są zweryfikowane backtestem, `);
H.push(`a oceny w horyzontach (▲ kupuj / ● trzymaj / ▼ sprzedaj / · brak danych) to opinia modelu na podstawie tych danych, nie prognoza.`);
H.push(`</div></td></tr>`);
H.push(`</table></td></tr></table></body></html>`);

const html = H.join('');

// ── plain-text fallback ───────────────────────────────────────────────────────
function odMarkdown(t) {
  return String(t || '')
    .replace(/\*\*([^*]+)\*\*/g, '$1')
    .replace(/(^|[\s(])\*([^*\n]+)\*/g, '$1$2')
    .replace(/`([^`]+)`/g, '$1')
    .trim();
}
const T = [];
T.push(`WIG20 — PRZEGLĄD DZIENNY · ${dzis}`);
T.push(`Wygenerowano ${godzina}${sesja ? ` · dane z sesji ${sesja}` : ''} · ${spolki.length} spółek`);
T.push(liczniki.map((b) => `${b.emoji} ${b.n} ${b.label.toLowerCase()}`).join('   '));
for (const o of ostrzezenia) { T.push(`\n⚠️  ${odMarkdown(o.replace(/<[^>]+>/g, ''))}`); }
if (naglowek) { T.push(`\n${odMarkdown(naglowek)}`); }
T.push(`\n${'═'.repeat(58)}\nCZĘŚĆ 1 · PRZEGLĄD\n${'═'.repeat(58)}`);
for (const b of BUCKETS) {
  const lista = wKoszyku(b.emoji);
  T.push(`\n${b.emoji} ${b.label.toUpperCase()} (${lista.length})`);
  T.push(lista.length
    ? lista.map((s) => `  • ${s.ticker} — ${odMarkdown(trescLinii(s))}\n    ${horizonsOf(s).map((h) => `${h.label} ${(VERDICTS[h.verdict] || VERDICTS.BRAK).mark}`).join('  ')}`).join('\n')
    : '  — brak');
}
if (makro) { T.push(`\n${'─'.repeat(58)}\nTŁO MAKRO\n${'─'.repeat(58)}\n${odMarkdown(makro)}`); }
if (zeSzczegolami.length) {
  T.push(`\n${'═'.repeat(58)}\nCZĘŚĆ 2 · SZCZEGÓŁY\n${'═'.repeat(58)}`);
  for (const { s, b } of zeSzczegolami) {
    const oceny = horizonsOf(s)
      .map((h) => `  ${h.label.padEnd(12)} ${(VERDICTS[h.verdict] || VERDICTS.BRAK).mark} ${h.verdict === 'BRAK' ? 'brak danych' : h.verdict.toLowerCase()}${h.why ? ` — ${odMarkdown(h.why)}` : ''}`)
      .join('\n');
    T.push(`\n${b.emoji} ${s.ticker} — ${odMarkdown(trescLinii(s))}\n${'─'.repeat(58)}\nOCENA W HORYZONTACH\n${oceny}\n\n${odMarkdown(s.details)}`);
  }
}
T.push(`\n${'─'.repeat(58)}\nTo analiza danych, nie rekomendacja inwestycyjna.`);
const text = T.join('\n');

const bilans = liczniki.filter((b) => b.n).map((b) => `${b.n}${b.emoji}`).join(' ');
const subject = ['WIG20 — przegląd ' + dzis, bilans, nieswieze.length ? '⚠️ dane nieświeże' : '']
  .filter(Boolean)
  .join(' · ');

return [{ json: { html, text, subject } }];
